--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

hl.layer_rule({
	name = "blur-waybar",
	match = {
		namespace = "waybar",
	},
	blur = true,
	ignore_alpha = 0.2,

	blur_popups = true,
})

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

hl.window_rule({
	name = "move-windscribe",
	match = { class = "Windscribe" }, -- recognize with "hyprctl clients"
	workspace = 5,
	float = true,
})

hl.window_rule({
	name = "calculator",
	match = { class = "org.gnome.Calculator" },
	float = true,
	center = true,
})

hl.window_rule({
	name = "clipboard-manager-clipse",
	match = { class = "clipse" },
	float = true,
	size = "622 652",
	center = true,
})

hl.window_rule({
	name = "telegram",
	match = { class = "org.telegram.desktop" },
	float = true,
	center = true,
})

hl.window_rule({
	name = "blueman-manager",
	match = { class = "blueman-manager" },
	float = true,
	center = true,
})

hl.window_rule({
	name = "network-manager-editor",
	match = { class = "nm-connection-editor" },
	float = true,
	center = true,
})
